USE [JamunaBankProcurement];
GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_SaveDraft @RequisitionId BIGINT=NULL,@RequestedByEmployeeId VARCHAR(30),@RequestedOrgUnitId BIGINT,@Justification NVARCHAR(2000),@Items dbo.RequisitionItemTableType READONLY,@SpecValues dbo.RequisitionSpecValueTableType READONLY,@SpecOptions dbo.RequisitionSpecOptionTableType READONLY,@Actor VARCHAR(50),@AllowSubmittedEdit BIT=0
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;IF NOT EXISTS(SELECT 1 FROM @Items) THROW 51000,'At least one item is required.',1;IF EXISTS(SELECT 1 FROM @Items WHERE REQ_TYPE NOT IN('NEW','REPLACEMENT','ADDITIONAL') OR QUANTITY<=0 OR ESTIMATED_UNIT_PRICE<0 OR NULLIF(PURPOSE_JUSTIFICATION,'') IS NULL OR (REQ_TYPE='REPLACEMENT' AND NULLIF(CURRENT_CONDITION,'') IS NULL)) THROW 51000,'One or more items are invalid.',1;IF EXISTS(SELECT 1 FROM @SpecValues v LEFT JOIN @Items i ON i.CLIENT_ITEM_KEY=v.CLIENT_ITEM_KEY LEFT JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_SPEC_ID=v.ASSET_SPEC_ID AND d.ASSET_ID=i.ASSET_ID AND d.IS_ACTIVE=1 WHERE i.CLIENT_ITEM_KEY IS NULL OR d.ASSET_SPEC_ID IS NULL OR (d.SPEC_TYPE='TEXT' AND (v.SPEC_TEXT_VALUE IS NULL OR v.SPEC_NUM_VALUE IS NOT NULL OR v.SPEC_DATE_VALUE IS NOT NULL OR v.SPEC_BOOL_VALUE IS NOT NULL)) OR (d.SPEC_TYPE='NUMBER' AND (v.SPEC_NUM_VALUE IS NULL OR v.SPEC_TEXT_VALUE IS NOT NULL OR v.SPEC_DATE_VALUE IS NOT NULL OR v.SPEC_BOOL_VALUE IS NOT NULL)) OR (d.SPEC_TYPE='DATE' AND (v.SPEC_DATE_VALUE IS NULL OR v.SPEC_TEXT_VALUE IS NOT NULL OR v.SPEC_NUM_VALUE IS NOT NULL OR v.SPEC_BOOL_VALUE IS NOT NULL)) OR (d.SPEC_TYPE='YES_NO' AND (v.SPEC_BOOL_VALUE IS NULL OR v.SPEC_TEXT_VALUE IS NOT NULL OR v.SPEC_NUM_VALUE IS NOT NULL OR v.SPEC_DATE_VALUE IS NOT NULL)) OR (d.SPEC_TYPE IN('DROPDOWN','MULTI_SELECT') AND (v.SPEC_TEXT_VALUE IS NOT NULL OR v.SPEC_NUM_VALUE IS NOT NULL OR v.SPEC_DATE_VALUE IS NOT NULL OR v.SPEC_BOOL_VALUE IS NOT NULL))) THROW 51000,'A dynamic specification value is invalid for its active definition.',1;IF EXISTS(SELECT 1 FROM @SpecOptions x JOIN @Items i ON i.CLIENT_ITEM_KEY=x.CLIENT_ITEM_KEY LEFT JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_SPEC_ID=x.ASSET_SPEC_ID AND d.ASSET_ID=i.ASSET_ID AND d.IS_ACTIVE=1 LEFT JOIN dbo.ASSET_SPEC_OPTION o ON o.ASSET_SPEC_OPTION_ID=x.ASSET_SPEC_OPTION_ID AND o.ASSET_SPEC_ID=x.ASSET_SPEC_ID AND o.IS_ACTIVE=1 WHERE d.SPEC_TYPE NOT IN('DROPDOWN','MULTI_SELECT') OR o.ASSET_SPEC_OPTION_ID IS NULL) THROW 51000,'A selected specification option is invalid or inactive.',1;IF EXISTS(SELECT 1 FROM @SpecValues v JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_SPEC_ID=v.ASSET_SPEC_ID WHERE d.SPEC_TYPE='DROPDOWN' AND (SELECT COUNT(*) FROM @SpecOptions o WHERE o.CLIENT_ITEM_KEY=v.CLIENT_ITEM_KEY AND o.ASSET_SPEC_ID=v.ASSET_SPEC_ID)<>1) OR EXISTS(SELECT 1 FROM @SpecValues v JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_SPEC_ID=v.ASSET_SPEC_ID WHERE d.SPEC_TYPE='MULTI_SELECT' AND NOT EXISTS(SELECT 1 FROM @SpecOptions o WHERE o.CLIENT_ITEM_KEY=v.CLIENT_ITEM_KEY AND o.ASSET_SPEC_ID=v.ASSET_SPEC_ID)) THROW 51000,'Dropdown requires one option and multi-select requires at least one option.',1;DECLARE @ResolvedItems dbo.RequisitionItemTableType;INSERT @ResolvedItems(CLIENT_ITEM_KEY,ASSET_ID,REQ_TYPE,QUANTITY,ESTIMATED_UNIT_PRICE,PURPOSE_JUSTIFICATION,ADDITIONAL_SPEC_REQUIREMENT,ASSET_TAG_NO,SERIAL_NO,CURRENT_CONDITION,REPLACEMENT_ADDITIONAL_INFO) SELECT i.CLIENT_ITEM_KEY,i.ASSET_ID,i.REQ_TYPE,i.QUANTITY,CONVERT(DECIMAL(18,2),COALESCE(v.DEFAULT_TOTAL_AMOUNT,0)/NULLIF(i.QUANTITY,0)),i.PURPOSE_JUSTIFICATION,i.ADDITIONAL_SPEC_REQUIREMENT,i.ASSET_TAG_NO,i.SERIAL_NO,i.CURRENT_CONDITION,i.REPLACEMENT_ADDITIONAL_INFO FROM @Items i OUTER APPLY(SELECT MAX(COALESCE(r.MAX_AMOUNT,r.MIN_AMOUNT)) DEFAULT_TOTAL_AMOUNT FROM dbo.WORKFLOW_RULE r WHERE r.ASSET_ID=i.ASSET_ID AND r.REQ_TYPE=i.REQ_TYPE AND r.IS_ACTIVE=1 AND r.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND(r.EFFECTIVE_TO IS NULL OR r.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))v;IF EXISTS(SELECT 1 FROM @ResolvedItems WHERE ESTIMATED_UNIT_PRICE<=0) THROW 51000,'No active workflow rule with an amount range is configured for one or more requisition items.',1;DECLARE @no VARCHAR(30);IF @RequisitionId IS NULL BEGIN SET @no=CONCAT('REQ-',CONVERT(CHAR(8),SYSUTCDATETIME(),112),'-',UPPER(LEFT(REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),10)));INSERT dbo.REQUISITION_HEADER(REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CREATED_BY) SELECT @no,@RequestedByEmployeeId,@RequestedOrgUnitId,@Justification,SUM(QUANTITY*ESTIMATED_UNIT_PRICE),@Actor FROM @ResolvedItems;SET @RequisitionId=SCOPE_IDENTITY();END ELSE BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId AND REQUESTED_BY_EMPLOYEE_ID=@RequestedByEmployeeId AND REQUESTED_ORG_UNIT_ID=@RequestedOrgUnitId AND (CURRENT_STATUS IN('DRAFT','MANAGER_RETURNED') OR (@AllowSubmittedEdit=1 AND CURRENT_STATUS='SUBMITTED')) AND IS_ACTIVE=1) THROW 51002,'Only the requester may edit an editable requisition.',1;IF @AllowSubmittedEdit=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STATUS='SUBMITTED')BEGIN UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1 AND ASSIGNMENT_TYPE='MANAGER';UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='DRAFT',MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId;END;SELECT @no=REQUISITION_NO FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId;DELETE o FROM dbo.REQUISITION_ITEM_SPEC_OPTION o JOIN dbo.REQUISITION_ITEM_SPEC s ON s.REQ_ITEM_SPEC_ID=o.REQ_ITEM_SPEC_ID JOIN dbo.REQUISITION_ITEM i ON i.REQ_ITEM_ID=s.REQ_ITEM_ID WHERE i.REQUISITION_ID=@RequisitionId;DELETE s FROM dbo.REQUISITION_ITEM_SPEC s JOIN dbo.REQUISITION_ITEM i ON i.REQ_ITEM_ID=s.REQ_ITEM_ID WHERE i.REQUISITION_ID=@RequisitionId;DELETE r FROM dbo.REQUISITION_REPLACEMENT_INFO r JOIN dbo.REQUISITION_ITEM i ON i.REQ_ITEM_ID=r.REQ_ITEM_ID WHERE i.REQUISITION_ID=@RequisitionId;DELETE dbo.REQUISITION_ITEM WHERE REQUISITION_ID=@RequisitionId;UPDATE dbo.REQUISITION_HEADER SET JUSTIFICATION=@Justification,TOTAL_ESTIMATED_AMOUNT=(SELECT SUM(QUANTITY*ESTIMATED_UNIT_PRICE) FROM @ResolvedItems),MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId;END;DECLARE @map TABLE(CLIENT_ITEM_KEY INT PRIMARY KEY,REQ_ITEM_ID BIGINT);MERGE dbo.REQUISITION_ITEM t USING(SELECT i.*,a.ASSET_NAME FROM @ResolvedItems i JOIN dbo.ASSET_MASTER a ON a.ASSET_ID=i.ASSET_ID AND a.IS_ACTIVE=1)s ON 1=0 WHEN NOT MATCHED THEN INSERT(REQUISITION_ID,ASSET_ID,ITEM_NAME_SNAPSHOT,REQ_TYPE,QUANTITY,ESTIMATED_UNIT_PRICE,PURPOSE_JUSTIFICATION,ADDITIONAL_SPEC_REQUIREMENT,CREATED_BY)VALUES(@RequisitionId,s.ASSET_ID,s.ASSET_NAME,s.REQ_TYPE,s.QUANTITY,s.ESTIMATED_UNIT_PRICE,s.PURPOSE_JUSTIFICATION,s.ADDITIONAL_SPEC_REQUIREMENT,@Actor)OUTPUT s.CLIENT_ITEM_KEY,inserted.REQ_ITEM_ID INTO @map;IF(SELECT COUNT(*) FROM @map)<>(SELECT COUNT(*) FROM @ResolvedItems)THROW 51000,'An asset is missing or inactive.',1;INSERT dbo.REQUISITION_REPLACEMENT_INFO(REQ_ITEM_ID,ASSET_TAG_NO,SERIAL_NO,CURRENT_CONDITION,ADDITIONAL_INFO,CREATED_BY)SELECT m.REQ_ITEM_ID,i.ASSET_TAG_NO,i.SERIAL_NO,i.CURRENT_CONDITION,i.REPLACEMENT_ADDITIONAL_INFO,@Actor FROM @ResolvedItems i JOIN @map m ON m.CLIENT_ITEM_KEY=i.CLIENT_ITEM_KEY WHERE i.REQ_TYPE='REPLACEMENT';DECLARE @specmap TABLE(CLIENT_ITEM_KEY INT,ASSET_SPEC_ID BIGINT,REQ_ITEM_SPEC_ID BIGINT,PRIMARY KEY(CLIENT_ITEM_KEY,ASSET_SPEC_ID));MERGE dbo.REQUISITION_ITEM_SPEC t USING(SELECT v.*,m.REQ_ITEM_ID,d.SPEC_NAME,d.SPEC_TYPE,d.IS_MANDATORY,d.DISPLAY_ORDER FROM @SpecValues v JOIN @map m ON m.CLIENT_ITEM_KEY=v.CLIENT_ITEM_KEY JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_SPEC_ID=v.ASSET_SPEC_ID)s ON 1=0 WHEN NOT MATCHED THEN INSERT(REQ_ITEM_ID,ASSET_SPEC_ID,SPEC_NAME_SNAPSHOT,SPEC_TYPE_SNAPSHOT,SPEC_TEXT_VALUE,SPEC_NUM_VALUE,SPEC_DATE_VALUE,SPEC_BOOL_VALUE,IS_MANDATORY_SNAPSHOT,DISPLAY_ORDER_SNAPSHOT,CREATED_BY)VALUES(s.REQ_ITEM_ID,s.ASSET_SPEC_ID,s.SPEC_NAME,s.SPEC_TYPE,s.SPEC_TEXT_VALUE,s.SPEC_NUM_VALUE,s.SPEC_DATE_VALUE,s.SPEC_BOOL_VALUE,s.IS_MANDATORY,s.DISPLAY_ORDER,@Actor)OUTPUT s.CLIENT_ITEM_KEY,s.ASSET_SPEC_ID,inserted.REQ_ITEM_SPEC_ID INTO @specmap;INSERT dbo.REQUISITION_ITEM_SPEC_OPTION(REQ_ITEM_SPEC_ID,ASSET_SPEC_OPTION_ID,SELECTED_OPTION_TEXT_SNAPSHOT,CREATED_BY)SELECT m.REQ_ITEM_SPEC_ID,x.ASSET_SPEC_OPTION_ID,o.OPTION_VALUE,@Actor FROM @SpecOptions x JOIN @specmap m ON m.CLIENT_ITEM_KEY=x.CLIENT_ITEM_KEY AND m.ASSET_SPEC_ID=x.ASSET_SPEC_ID JOIN dbo.ASSET_SPEC_OPTION o ON o.ASSET_SPEC_OPTION_ID=x.ASSET_SPEC_OPTION_ID;COMMIT;SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@RequisitionId ENTITY_ID,@no REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE WHEN ERROR_NUMBER()=51000 THEN'001' WHEN ERROR_NUMBER()=51002 THEN'003' WHEN ERROR_NUMBER()IN(2601,2627)THEN'005' ELSE'999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_GetMakerDetail @RequisitionId BIGINT,@RequesterEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_BY_EMPLOYEE_ID,h.REQUESTED_ORG_UNIT_ID,o.ORG_UNIT_NAME,h.REQUESTED_DATE,h.JUSTIFICATION,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS,COALESCE(w.CURRENT_STAGE,CASE a.ASSIGNMENT_TYPE WHEN'MANAGER'THEN'MANAGER'WHEN'PROCUREMENT_OFFICER_POOL'THEN'PROCUREMENT_OFFICER'WHEN'CONCERN_OFFICIAL'THEN'CONCERN_DIVISION'WHEN'CONCERN_AUTHORITY'THEN'CONCERN_AUTHORITY'WHEN'PROCUREMENT_AUTHORITY_POOL'THEN'PROCUREMENT_AUTHORITY'WHEN'MAKER'THEN'MAKER'ELSE h.CURRENT_STATUS END)PENDING_STAGE,a.ASSIGNED_TO_EMPLOYEE_ID PENDING_WITH_EMPLOYEE_ID,u.DISPLAY_NAME PENDING_WITH_NAME,CASE WHEN a.ASSIGNED_TO_EMPLOYEE_ID IS NOT NULL THEN COALESCE(u.DISPLAY_NAME,a.ASSIGNED_TO_EMPLOYEE_ID) WHEN a.ASSIGNMENT_TYPE='MANAGER'THEN CONCAT('Branch Manager Pool - ',COALESCE(ao.ORG_UNIT_NAME,o.ORG_UNIT_NAME)) WHEN a.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL'THEN'Procurement Officer Pool' WHEN a.ASSIGNMENT_TYPE='CONCERN_OFFICIAL'THEN CONCAT('Concern Official Pool - ',COALESCE(ao.ORG_UNIT_NAME,'Concern Division')) WHEN a.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'THEN CONCAT('Concern Division Authority Pool - ',COALESCE(ao.ORG_UNIT_NAME,'Concern Division')) WHEN a.ASSIGNMENT_TYPE='PROCUREMENT_AUTHORITY_POOL'THEN'Procurement Authority Pool' WHEN a.ASSIGNMENT_TYPE='MAKER'THEN'Maker' ELSE NULL END PENDING_WITH_LABEL FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID OUTER APPLY(SELECT TOP(1)x.ASSIGNMENT_TYPE,x.ASSIGNED_TO_EMPLOYEE_ID,x.ASSIGNED_TO_ORG_UNIT_ID FROM dbo.REQUISITION_ASSIGNMENT x WHERE x.REQUISITION_ID=h.REQUISITION_ID AND x.IS_CURRENT=1 ORDER BY x.ASSIGNED_DATE DESC,x.ASSIGNMENT_ID DESC)a LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=a.ASSIGNED_TO_EMPLOYEE_ID LEFT JOIN dbo.ORG_UNIT ao ON ao.ORG_UNIT_ID=a.ASSIGNED_TO_ORG_UNIT_ID LEFT JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID AND w.COMPLETED_DATE IS NULL WHERE h.REQUISITION_ID=@RequisitionId AND h.REQUESTED_BY_EMPLOYEE_ID=@RequesterEmployeeId AND h.IS_ACTIVE=1;SELECT i.* FROM dbo.REQUISITION_ITEM i JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=i.REQUISITION_ID WHERE i.REQUISITION_ID=@RequisitionId AND h.REQUESTED_BY_EMPLOYEE_ID=@RequesterEmployeeId AND i.IS_ACTIVE=1 ORDER BY i.REQ_ITEM_ID;SELECT s.*,o.REQ_ITEM_SPEC_OPTION_ID,o.ASSET_SPEC_OPTION_ID,o.SELECTED_OPTION_TEXT_SNAPSHOT FROM dbo.REQUISITION_ITEM_SPEC s JOIN dbo.REQUISITION_ITEM i ON i.REQ_ITEM_ID=s.REQ_ITEM_ID JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=i.REQUISITION_ID LEFT JOIN dbo.REQUISITION_ITEM_SPEC_OPTION o ON o.REQ_ITEM_SPEC_ID=s.REQ_ITEM_SPEC_ID WHERE h.REQUISITION_ID=@RequisitionId AND h.REQUESTED_BY_EMPLOYEE_ID=@RequesterEmployeeId ORDER BY s.REQ_ITEM_ID,s.DISPLAY_ORDER_SNAPSHOT,o.REQ_ITEM_SPEC_OPTION_ID;SELECT r.* FROM dbo.REQUISITION_REPLACEMENT_INFO r JOIN dbo.REQUISITION_ITEM i ON i.REQ_ITEM_ID=r.REQ_ITEM_ID JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=i.REQUISITION_ID WHERE h.REQUISITION_ID=@RequisitionId AND h.REQUESTED_BY_EMPLOYEE_ID=@RequesterEmployeeId;SELECT a.ATTACHMENT_ID,a.ENTITY_TYPE,a.ENTITY_ID,a.FILE_NAME,a.ORIGINAL_FILE_NAME,a.FILE_EXTENSION,a.MIME_TYPE,a.FILE_SIZE,a.DOCUMENT_TYPE,a.UPLOADED_DATE FROM dbo.ATTACHMENT a WHERE a.ENTITY_TYPE='REQUISITION' AND a.ENTITY_ID=@RequisitionId AND a.IS_ACTIVE=1;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_GetMine @RequesterEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.JUSTIFICATION,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS,(SELECT COUNT(*) FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)ITEM_COUNT FROM dbo.REQUISITION_HEADER h WHERE h.REQUESTED_BY_EMPLOYEE_ID=@RequesterEmployeeId AND h.IS_ACTIVE=1 ORDER BY h.REQUESTED_DATE DESC;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_GetBranchRequester @RequisitionId BIGINT,@RequestedOrgUnitId BIGINT=NULL
AS BEGIN SET NOCOUNT ON;SELECT h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h WHERE h.REQUISITION_ID=@RequisitionId AND(@RequestedOrgUnitId IS NULL OR h.REQUESTED_ORG_UNIT_ID=@RequestedOrgUnitId)AND h.IS_ACTIVE=1;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_GetBranchAll @RequestedOrgUnitId BIGINT=NULL,@RequisitionNo VARCHAR(30)=NULL,@AssetId BIGINT=NULL,@RequisitionType VARCHAR(20)=NULL,@Status VARCHAR(40)=NULL,@FromDate DATE=NULL,@ToDate DATE=NULL
AS BEGIN
 SET NOCOUNT ON;
 SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.REQUESTED_BY_EMPLOYEE_ID,COALESCE(u.DISPLAY_NAME,h.REQUESTED_BY_EMPLOYEE_ID) REQUESTED_BY_NAME,o.ORG_UNIT_NAME,
  COALESCE((SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),x.ITEM_NAME_SNAPSHOT),', ') FROM(SELECT DISTINCT i.ITEM_NAME_SNAPSHOT FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)x),'') ASSETS,
  COALESCE((SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),x.REQ_TYPE),', ') FROM(SELECT DISTINCT i.REQ_TYPE FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)x),'') REQUISITION_TYPES,
  COALESCE((SELECT SUM(i.QUANTITY) FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1),0) TOTAL_QUANTITY,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS,
  COALESCE(w.CURRENT_STAGE,CASE a.ASSIGNMENT_TYPE WHEN'MANAGER'THEN'MANAGER' WHEN'PROCUREMENT_OFFICER_POOL'THEN'PROCUREMENT_OFFICER' WHEN'CONCERN_OFFICIAL'THEN'CONCERN_DIVISION' WHEN'CONCERN_AUTHORITY'THEN'CONCERN_AUTHORITY' WHEN'PROCUREMENT_AUTHORITY_POOL'THEN'PROCUREMENT_AUTHORITY' WHEN'MAKER'THEN'MAKER' ELSE h.CURRENT_STATUS END) PENDING_STAGE,
  CASE WHEN a.ASSIGNED_TO_EMPLOYEE_ID IS NOT NULL THEN COALESCE(au.DISPLAY_NAME,a.ASSIGNED_TO_EMPLOYEE_ID) WHEN a.ASSIGNMENT_TYPE='MANAGER'THEN CONCAT('Branch Manager Pool - ',o.ORG_UNIT_NAME) WHEN a.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL'THEN'Procurement Officer Pool' WHEN a.ASSIGNMENT_TYPE='CONCERN_OFFICIAL'THEN'Concern Official Pool' WHEN a.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'THEN'Concern Division Authority Pool' WHEN a.ASSIGNMENT_TYPE='PROCUREMENT_AUTHORITY_POOL'THEN'Procurement Authority Pool' WHEN a.ASSIGNMENT_TYPE='MAKER'THEN'Maker' ELSE NULL END PENDING_WITH
 FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID
 OUTER APPLY(SELECT TOP(1)x.ASSIGNMENT_TYPE,x.ASSIGNED_TO_EMPLOYEE_ID FROM dbo.REQUISITION_ASSIGNMENT x WHERE x.REQUISITION_ID=h.REQUISITION_ID AND x.IS_CURRENT=1 ORDER BY x.ASSIGNED_DATE DESC,x.ASSIGNMENT_ID DESC)a
 LEFT JOIN dbo.APP_USER_CACHE au ON au.EMPLOYEE_ID=a.ASSIGNED_TO_EMPLOYEE_ID LEFT JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID AND w.COMPLETED_DATE IS NULL
 WHERE(@RequestedOrgUnitId IS NULL OR h.REQUESTED_ORG_UNIT_ID=@RequestedOrgUnitId)AND h.IS_ACTIVE=1 AND(NULLIF(@RequisitionNo,'')IS NULL OR h.REQUISITION_NO LIKE '%'+@RequisitionNo+'%') AND(NULLIF(@Status,'')IS NULL OR h.CURRENT_STATUS=@Status) AND(@FromDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)>=@FromDate) AND(@ToDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)<=@ToDate)
 AND(@AssetId IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.ASSET_ID=@AssetId AND i.IS_ACTIVE=1)) AND(NULLIF(@RequisitionType,'')IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.REQ_TYPE=@RequisitionType AND i.IS_ACTIVE=1))
 ORDER BY h.REQUESTED_DATE DESC;
END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_SubmitValidated @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;IF EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_ID=i.ASSET_ID AND d.IS_ACTIVE=1 AND d.IS_MANDATORY=1 LEFT JOIN dbo.REQUISITION_ITEM_SPEC s ON s.REQ_ITEM_ID=i.REQ_ITEM_ID AND s.ASSET_SPEC_ID=d.ASSET_SPEC_ID WHERE i.REQUISITION_ID=@RequisitionId AND i.IS_ACTIVE=1 AND(s.REQ_ITEM_SPEC_ID IS NULL OR(d.SPEC_TYPE='TEXT'AND s.SPEC_TEXT_VALUE IS NULL)OR(d.SPEC_TYPE='NUMBER'AND s.SPEC_NUM_VALUE IS NULL)OR(d.SPEC_TYPE='DATE'AND s.SPEC_DATE_VALUE IS NULL)OR(d.SPEC_TYPE='YES_NO'AND s.SPEC_BOOL_VALUE IS NULL)OR(d.SPEC_TYPE='DROPDOWN'AND(SELECT COUNT(*)FROM dbo.REQUISITION_ITEM_SPEC_OPTION o WHERE o.REQ_ITEM_SPEC_ID=s.REQ_ITEM_SPEC_ID)<>1)OR(d.SPEC_TYPE='MULTI_SELECT'AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM_SPEC_OPTION o WHERE o.REQ_ITEM_SPEC_ID=s.REQ_ITEM_SPEC_ID))))THROW 51000,'Mandatory specification values are incomplete.',1;EXEC dbo.usp_Requisition_Submit @RequisitionId,@ActorEmployeeId,@Remarks,NULL;COMMIT;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
